import type { Category, Place } from '@faresight/shared';
import network from './network.json';
import placePhotos from './place-photos.json';

// Generated by scripts/build-map-data.mjs from the same sources as the 3D models.
export interface NetworkLine {
  id: string;
  routeId: string;
  name: string;
  /** The line's official colour, used for its track. */
  color: string;
  /** The brighter colour the sculpture gives the line's trains. */
  core: string;
  /** Flat x, y pairs: the sculpture's track seen from above. */
  points: number[];
}
export interface NetworkStation {
  name: string;
  x: number;
  y: number;
  routes: string[];
  colors: string[];
  stopId?: string;
  code?: string;
}
export interface NetworkData {
  bounds: number[];
  /** The ground the network floats on, and the wider ring where it fades out. */
  ground: string;
  groundRim: string;
  /** The Charles and the channels between Boston's peninsulas. */
  water: string;
  lines: NetworkLine[];
  stations: NetworkStation[];
}

export type AreaLayer = 'water' | 'park' | 'pitch' | 'foot' | 'service' | 'minor' | 'major' | 'building';
export interface AreaData {
  stopId: string;
  name: string;
  spanMeters: number;
  unitsPerMeter: number;
  centerLat: number;
  centerLon: number;
  station: number[];
  /** The island's shoreline as x, y pairs, the width of its turf margin, and the box that holds both. */
  outline: number[];
  turf: number;
  bounds: number[];
  layers: Record<AreaLayer, string>;
  labels: { name: string; x: number; y: number }[];
  attribution: string;
}

export const networkData: NetworkData = network;

/** A freely licensed photo for a place, found by scripts/find-place-photos.mjs. The licence asks for the credit to be shown. */
export interface PlacePhoto {
  url: string;
  width: number;
  height: number;
  credit: string;
  license: string;
  license_url: string | null;
  /** The page the photo comes from, which the credit links to. */
  page: string;
  provider: string;
  /** The photo shows the building, square or street the place is on, not the place itself. */
  nearby?: boolean;
  /** Said on the photo when it shows the business but not as it stands today, e.g. "Earlier location". */
  tag?: string;
}

const photos: Record<string, PlacePhoto | undefined> = placePhotos;

export const placePhoto = (placeId: string) => photos[placeId];

const areaLoaders = import.meta.glob<{ default: AreaData }>('./areas/*.json');

export async function loadArea(stopId: string): Promise<AreaData> {
  const loader = areaLoaders[`./areas/${stopId}.json`];
  if (!loader) throw new Error('This stop has no neighborhood map yet.');
  return (await loader()).default;
}

/** Projects a coordinate onto an area's flat map, matching the diorama deck projection. */
export function projectToArea(area: AreaData, lat: number, lon: number): [number, number] {
  return [
    (lon - area.centerLon) * 111320 * Math.cos(area.centerLat * Math.PI / 180) * area.unitsPerMeter,
    -(lat - area.centerLat) * 110540 * area.unitsPerMeter,
  ];
}

const categoryNames: Record<Category, string> = {
  restaurant: 'Restaurant', study: 'Study café', music: 'Live music', activity: 'Activity', shop: 'Shop',
  market: 'Market', outdoor: 'Outdoors', museum: 'Museum', event_space: 'Event space', hotel: 'Hotel', stadium: 'Stadium',
};

export function categoryLabel(place: Place) {
  const tag = place.category === 'restaurant' ? place.cravings[0]
    : place.cravings.includes('karaoke') ? 'karaoke' : undefined;
  return tag ? tag.charAt(0).toUpperCase() + tag.slice(1) : categoryNames[place.category];
}

/** What people say about a place, boiled down to one rating and one line. */
export interface ReviewSummary {
  rating?: number;
  /** Where the rating comes from: Vantage's own reviews, or a public source such as Tripadvisor. */
  source?: string;
  quote?: string;
}

export function reviewSummary(place: Place): ReviewSummary {
  // Sample notes carry no stars. Reviews from real visitors do, and they count before any outside rating.
  const rated = place.reviews.filter((review) => review.rating > 0);
  const outside = place.details?.ratings[0];
  const written = place.reviews.filter((review) => !review.sample).at(-1);
  return {
    rating: rated.length ? rated.reduce((sum, review) => sum + review.rating, 0) / rated.length : outside?.rating,
    source: rated.length ? 'Vantage' : outside?.source,
    quote: written?.text ?? place.details?.review_highlights[0] ?? place.reviews[0]?.text,
  };
}

/** Dishes only make sense where food is served. */
export function servesDishes(place: Place) {
  return place.dishes.length > 0 || ['restaurant', 'study', 'market'].includes(place.category);
}

export interface Coverage {
  room: boolean;
  dishes: number;
  dishesDone: number;
}

export function coverage(place: Place): Coverage {
  return {
    room: Boolean(place.room_asset_id),
    dishes: place.dishes.length,
    dishesDone: place.dishes.filter((dish) => dish.asset ?? dish.asset_id).length,
  };
}
